sp_widget.css:
.img-styling{
  height: 50% !important;
  width: 50% !important;
  max-width: 100%;
}
div{
	text-align: left;
}

/* tablets */
@media (max-width: 991px){
  .img-styling{
    width: 75% !important;
    height: auto !important;
  }
}

/* phones */
@media (max-width: 767px){
  .img-styling{
    width: 100% !important;
    height: auto !important;
  }
}

sp_widget.script:
// data.slides = $sp.getRelatedList('sp_carousel_slide','carousel');

data.slides = [];
var slideConfig = [
	{	image: '/x_1921751_employ_0.extra_leave_credit_image.png',
	  url: '?id=sc_cat_item&sys_id=2357dfb7c3578b1043d978cc050131ef' },
	{ image: '/x_1921751_employ_0.spot_image1.jpeg',
	  url: '?id=sc_cat_item&sys_id=9f237aa7c3dfc71043d978cc050131d2' },
	{ image: '/x_1921751_employ_0.spot_high_value_image.jpeg',
	  url: '?id=sc_cat_item&sys_id=9f237aa7c3dfc71043d978cc050131d2' },
	{ image: '/x_1921751_employ_0.team_recognition_award_image.jpeg',
	  url: '?id=sc_cat_item&sys_id=47b75fbfc35f4b1043d978cc05013180' },
	{ image: '/x_1921751_employ_0.voucher_image.jpeg',
	  url: '?id=sc_cat_item&sys_id=722757b7c3578b1043d978cc0501318b' }
];

var gr = new GlideRecordSecure('x_1921751_employ_0_reward_catalog');
gr.addQuery('active', true);
gr.orderBy('reward_type');
gr.query();
var i = 0;
while (gr.next()) {
	var cfg = slideConfig[i % slideConfig.length];
	data.slides.push({
		name: gr.getDisplayValue('reward_type'),
		alt_text: gr.getDisplayValue('reward_type'),
		description: gr.getDisplayValue('description'),
		background: cfg.image,
		url: cfg.url
	});
	i++;
}
